const jwt = require('jsonwebtoken');
const env = require('../config/env');
const AppError = require('../utils/AppError');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return next(new AppError('Acesso negado. Token não fornecido.', 401));
  }

  try {
    req.user = jwt.verify(token, env.JWT_SECRET);
    next();
  } catch (error) {
    return next(new AppError('Token inválido ou expirado.', 401));
  }
};

const authorizeUserOwner = (req, res, next) => {
  const resourceId = parseInt(req.params.id, 10);

  if (req.user.userId !== resourceId) {
    return next(new AppError('Acesso negado. Você não tem permissão para modificar ou visualizar este recurso.', 403));
  }

  next();
};

module.exports = { authenticateToken, authorizeUserOwner };

const env = require('../config/env');

const errorHandler = (err, req, res, next) => {
  // Log no servidor apenas se o erro não for operacional
  if (!err.isOperational) console.error('🔥 ERROR START 🔥\n', err, '\n🔥 ERROR END 🔥');

  const statusCode = err.statusCode || 500;

  // Oculta detalhes do erro interno para o cliente
  const message = err.isOperational 
    ? err.message 
    : 'Ocorreu um erro interno no servidor.';

  res.status(statusCode).json({
    status: 'error',
    message,
    // Envia a stack trace apenas em ambiente de desenvolvimento
    ...(env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

module.exports = errorHandler;

const app = require('./app');
const env = require('./config/env');
const prisma = require('./config/db');

const server = app.listen(env.PORT, () => {
  console.log(`🚀 Servidor rodando no modo ${env.NODE_ENV} na porta ${env.PORT}`);
});

// Desligamento Gracioso (Graceful Shutdown)
const gracefulShutdown = async (signal) => {
  console.log(`\n🛑 Recebido ${signal}. Desligando graciosamente...`);

  server.close(async () => {
    console.log('HTTP server fechado.');
    await prisma.$disconnect();
    console.log('Conexão com Banco de Dados encerrada.');
    process.exit(0);
  });
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

const { z } = require('zod');

const createUserSchema = z.object({
  name: z.string().min(3, 'O nome deve ter pelo menos 3 caracteres.').trim(),
  email: z.string().email('Formato de email inválido.').trim().toLowerCase(),
  password: z.string().min(8, 'A senha deve ter pelo menos 8 caracteres.')
});

const loginSchema = z.object({
  email: z.string().email('Formato de email inválido.').trim().toLowerCase(),
  password: z.string().min(1, 'A senha é obrigatória.')
});

const updateUserSchema = z.object({
  name: z.string().min(3, 'O nome deve ter pelo menos 3 caracteres.').trim().optional(),
  email: z.string().email('Formato de email inválido.').trim().toLowerCase().optional(),
  password: z.string().min(8, 'A senha deve ter pelo menos 8 caracteres.').optional()
}).refine(data => Object.keys(data).length > 0, {
  message: "Pelo menos um campo deve ser fornecido para atualização."
});

module.exports = { createUserSchema, loginSchema, updateUserSchema };
